insert into public.pokedex_entries (dex, number, species_id, is_default, ko_description, en_description) values
  ('sinnoh', 152, 479, true, '플라스마로 된 몸으로 다양한 기계에 숨는다. 놀라게 하는 걸 매우 좋아한다.', 'Its electric-like body can enter some kinds of machines and take control in order to make mischief.'),
  ('sinnoh', 152, 10058, false, '플라스마로 된 몸으로 다양한 기계에 숨는다. 놀라게 하는 걸 매우 좋아한다.', 'Its electric-like body can enter some kinds of machines and take control in order to make mischief.'),
  ('sinnoh', 152, 10059, false, '플라스마로 된 몸으로 다양한 기계에 숨는다. 놀라게 하는 걸 매우 좋아한다.', 'Its electric-like body can enter some kinds of machines and take control in order to make mischief.'),
  ('sinnoh', 152, 10060, false, '플라스마로 된 몸으로 다양한 기계에 숨는다. 놀라게 하는 걸 매우 좋아한다.', 'Its electric-like body can enter some kinds of machines and take control in order to make mischief.'),
  ('sinnoh', 152, 10061, false, '플라스마로 된 몸으로 다양한 기계에 숨는다. 놀라게 하는 걸 매우 좋아한다.', 'Its electric-like body can enter some kinds of machines and take control in order to make mischief.'),
  ('sinnoh', 152, 10062, false, '플라스마로 된 몸으로 다양한 기계에 숨는다. 놀라게 하는 걸 매우 좋아한다.', 'Its electric-like body can enter some kinds of machines and take control in order to make mischief.'),
  ('sinnoh', 153, 207, true, '소리 내지 않고 미끄러지듯 활공한다. 양손의 커다란 손톱과 발의 발톱으로 먹이의 얼굴에 달라붙어 독침을 찌른다.', 'It glides as if sliding. It startles foes by clamping on to their faces, then jabs with its poison stinger.'),
  ('sinnoh', 154, 472, true, '날갯소리를 내지 않고 하늘을 난다. 긴 꼬리로 먹이를 잡아 송곳니로 급소를 공격한다.', 'If it succeeds in catching even a faint breeze properly, it can circle the globe without flapping once.'),
  ('sinnoh', 155, 299, true, '강력한 자력으로 먹이를 끌어당겨 움직이지 않고 사냥을 하지만 천적을 끌어당기는 일도 있다.', 'When endangered, it may protect itself by raising its magnetism and drawing iron objects to its body.'),
  ('sinnoh', 156, 476, true, '3개의 작은 유닛을 사용해서 먹이를 잡거나 적과 싸운다. 본체는 거의 명령할 뿐이다.', 'It freely controls three small units called Mini-Noses using magnetic force.'),
  ('sinnoh', 157, 280, true, '빨간 뿔로 사람이나 포켓몬의 따뜻한 마음을 캐치하면 전신이 미약하게 뜨거워진다.', 'If its horns capture the warm feelings of people or Pokémon, its body warms up slightly.'),
  ('sinnoh', 158, 281, true, '사이코 파워를 조작해 주변의 공간을 일그러뜨려 미래를 내다볼 수 있다.', 'If its Trainer becomes happy, it overflows with energy, dancing joyously while spinning about.'),
  ('sinnoh', 159, 282, true, '트레이너를 지키기 위해서라면 사이코 파워를 모두 써서 작은 블랙홀을 만들어 낸다.', 'To protect its Trainer, it will expend all its psychic power to create a small black hole.'),
  ('sinnoh', 160, 475, true, '도움을 구하는 감정을 민감하게 캐치해서 상대가 있는 곳으로 급히 달려가 가세한다.', 'When trying to protect someone, it extends its elbows as if they were swords and fights savagely.'),
  ('sinnoh', 161, 108, true, '벌레포켓몬이 주된 먹이다. 긴 혀로 상대를 핥아 마비시킨 후 통째로 삼킨다.', 'When it extends its over-six-foot- long tongue, its tail quivers. There is a possibility they are connected.'),
  ('sinnoh', 162, 463, true, '사람의 팔과 견줄 수 있을 정도의 활용도 높은 혀로 뭐든지 한다. 반대로 손은 무디다.', 'The long tongue is always soggy with slobber. The saliva contains a solvent that causes numbness.'),
  ('sinnoh', 163, 133, true, '불안정한 유전자 덕분에 여러 가지 진화의 가능성을 가지고 있는 특수한 포켓몬.', 'Because its genetic makeup is irregular, it quickly changes its form due to a variety of causes.'),
  ('sinnoh', 164, 134, true, '몸의 세포 구조가 물 분자와 닮았다. 물에 녹으면 보이지 않는다.', 'Its cell composition is similar to water molecules. As a result, it can melt away into water.'),
  ('sinnoh', 165, 135, true, '공기 중의 마이너스 이온을 빨아들여 약 10000볼트의 전기를 내뱉을 수 있다.', 'If agitated, it uses electricity to straighten out its fur and launch it in small bunches.'),
  ('sinnoh', 166, 136, true, '들이마신 공기 중 일부는 체내의 불꽃 주머니로 보내져 1700도의 불꽃이 된다.', 'Inhaled air is heated in the flame sac in its body to an intense fire over 3,000 degrees Fahrenheit.'),
  ('sinnoh', 167, 196, true, '이마의 구슬에서 사이코 파워를 방사해서 싸운다. 파워가 다하면 구슬의 색이 흐려진다.', 'Its fur is so sensitive, it can sense minute shifts in the air and predict the weather.'),
  ('sinnoh', 168, 197, true, '보름달이 뜬 밤이나 흥분했을 때 전신의 고리 무늬가 노랗게 빛난다.', 'When exposed to the moon’s aura, the rings on its body glow faintly and it gains a mysterious power.'),
  ('sinnoh', 169, 470, true, '꼬리는 날카로운 칼날 같다. 큰 나무도 두 동강 내는 탁월한 예리함을 자랑한다.', 'It basically does not fight. With cells similar to those of plants, it can perform photosynthesis.'),
  ('sinnoh', 170, 471, true, '글레이시아가 발산하는 냉기는 가루눈을 만들어 내기 때문에 스키장에서 인기가 높다.', 'By controlling its body heat, it can freeze the atmosphere around it to make a diamond-dust flurry.'),
  ('sinnoh', 171, 333, true, '솜구름처럼 보이기 때문에 적의 눈에 잘 띄지 않는다. 세대를 거치면서 날개가 하얗게 되었다고 한다.', 'It can’t relax if it or its surroundings are not clean. It wipes off dirt with its wings.'),
  ('sinnoh', 172, 334, true, '온순한 성질이지만 화나게 하면 날카로운 울음소리로 위협하며 가차 없이 공격한다.', 'If it bonds with a person, it will gently envelop the friend with its soft wings, then hum.'),
  ('sinnoh', 173, 175, true, '행운의 상징이다. 껍질 안에는 행복이 가득 담겨 있다고 한다.', 'It transforms the kindness and joy of others into happiness, which it stores in its shell.'),
  ('sinnoh', 174, 176, true, '상냥한 사람 곁에 있지 않으면 기운을 내지 못한다. 날개를 움직이지 않고도 공중에 뜰 수 있다.', 'To share its happiness, it flies around the world seeking kindhearted people.'),
  ('sinnoh', 175, 468, true, '은총을 베푸는 존재로 전해지고 있으며 먼 옛날부터 길조로 묘사되어 왔다.', 'It shares many blessings with people who respect one another’s rights and avoid needless strife.'),
  ('sinnoh', 176, 228, true, '동이 트기 전에 기분 나쁜 울음을 반복하여 자신들 무리의 존재를 어필한다.', 'It is smart enough to hunt in packs. It uses a variety of cries for communicating with others.'),
  ('sinnoh', 177, 229, true, '기분 나쁜 울음소리가 특징이다. 옛날 사람들은 지옥에서 온 사자라고 여겨 두려워했다.', 'The flames it breathes when angry contain toxins. If they cause a burn, it will hurt forever.'),
  ('sinnoh', 178, 81, true, '전기를 먹으며 살아간다. 좌우의 유닛에서 전기자석파를 방사하며 하늘을 난다.', 'The faster the units at its sides rotate, the greater the magnetic force they generate.'),
  ('sinnoh', 179, 82, true, '강한 자력을 끊임없이 발산한다. 레어코일이 접근하면 대부분의 컴퓨터에 이상 현상이 발생한다.', 'Many mysteriously appear when more sunspots dot the sun. They stop TV sets from displaying properly.'),
  ('sinnoh', 180, 462, true, '특수한 자기장의 영향으로 몸의 분자 구조가 변화해 진화했다고 여겨지고 있다.', 'A group tried to use scientific means to make MAGNEZONE evolve, but their efforts ended in failure.'),
  ('sinnoh', 181, 114, true, '덩굴은 독특한 향이 난다. 가라르 일부 지역에서는 허브로 사용되고 있다.', 'The blue vines shrouding its body are covered in a growth of fine hair. It is known to be ticklish.'),
  ('sinnoh', 182, 465, true, '따듯한 땅에서 살수록 덩굴의 성장이 빠르다. 길어지면 스스로 잘라내어 짧게 만든다.', 'Its arms are made of plants that bind themselves to things. They grow back right away if cut.'),
  ('sinnoh', 183, 193, true, '눈알을 움직이지 않고 360도를 볼 수 있다. 급브레이크나 방향 전환이 특기다. 노린 먹이를 빠르게 몰아넣는다.', 'It can hover in one spot by flapping its wings at high speed. It flits about to guard its territory.'),
  ('sinnoh', 184, 469, true, '6개의 다리로 어른을 껴안고도 너끈히 날 수 있다. 꼬리의 날개로 균형을 잡는다.', 'Its jaw power is incredible. It is adept at biting apart foes while flying by at high speed.'),
  ('sinnoh', 185, 357, true, '목에 난 송이는 맛있어서 인기다. 따뜻한 장소에는 트로피우스를 키우는 목장이 많다.', 'Delicious fruits grew out from around its neck because it always ate the same kind of fruit.'),
  ('sinnoh', 186, 111, true, '한 가지만 기억할 수 있다. 돌진하기 시작하면 이유가 무엇이었든 금방 잊어버린다.', 'Its powerful tackles can destroy anything. However, it is too slow witted to help people work.'),
  ('sinnoh', 187, 112, true, '전신을 갑옷 같은 피부로 보호하고 있다. 2000도의 마그마 속에서도 살 수 있다.', 'Standing on its hind legs freed its forelegs and made it smarter. It is very forgetful, however.'),
  ('sinnoh', 188, 464, true, '프로텍터로 공격을 튕겨내고 상대가 풀이 죽으면 특징적인 드릴로 관통한다.', 'It can launch a rock held in its hand like a missile by tightening then expanding muscles instantly.'),
  ('sinnoh', 189, 355, true, '모습을 투명하게 하고 몰래 먹잇감에 다가간다. 두꺼운 벽을 통과하는 능력을 지녔다.', 'It loves the crying of children. It startles bad kids by passing through walls and making them cry.'),
  ('sinnoh', 190, 356, true, '떠도는 사람의 영혼을 찾아 텅 빈 체내로 빨아들인다. 그 후 영혼이 어떻게 되는지는 알 수 없다.', 'It seeks drifting will-o’-the-wisps and sucks them into its empty body. What happens inside is a mystery.'),
  ('sinnoh', 191, 477, true, '노린 상대를 배의 입으로 통째로 삼킨다. 영혼만 먹은 뒤 육체는 뱉어내고 떠난다.', 'It is said to take lost spirits into its pliant body and guide them home.'),
  ('sinnoh', 192, 137, true, '근래에는 컴퓨터 공간에서 대활약한다. 수상한 데이터가 없는지 체크하며 돌아다닌다.', 'A man-made Pokémon created using advanced scientific means. It can move freely in cyberspace.'),
  ('sinnoh', 193, 233, true, 'AI 기능을 탑재한 결과 폴리곤2끼리만 통하는 수수께끼의 언어로 말하기 시작했다.', 'It was upgraded to enable the exploration of other planets. However, it failed to measure up.'),
  ('sinnoh', 194, 474, true, '추가 프로그램으로 진화했다고 전해지지만 정말 진화인 건지 학회에서도 의견이 나뉜다.', 'Its programming was modified to enable work in alien dimensions. It did not work as planned.'),
  ('sinnoh', 195, 123, true, '숲속에서 많은 나무가 베인 채 쓰러져 있는 장소를 발견했다면 그곳은 스라크의 영역이다.', 'The sharp scythes on its forearms become increasingly sharp by cutting through hard objects.'),
  ('sinnoh', 196, 212, true, '몸은 가늘지만 공격력은 무시무시하다. 몸의 근육도 금속으로 되어 있다.', 'It raises its pincers with eyelike markings for intimidation. It also swings them down dangerously.'),
  ('sinnoh', 197, 239, true, '아직 전기를 모으는 게 서툴다. 전기를 먹기 위해 민가에 숨어들어 콘센트를 찾는다.', 'A weak electric current flows between its horns. Sticking a hand there shocks the unwary.'),
  ('sinnoh', 198, 125, true, '폭풍이 치면 높은 나무 주위에 모여 번개가 떨어지기를 가만히 기다린다.', 'It windmills its arms to slightly boost its punches. Foes have been known to escape in the meantime.'),
  ('sinnoh', 199, 466, true, '발전량은 전기포켓몬 중에서도 손꼽히는 수준이다. 꼬리 끝에서 고압 전류를 방전한다.', 'Heedless of enemy attacks, it closes in, shoves its tails onto the foe, then looses high voltage.'),
  ('sinnoh', 200, 240, true, '화산 주위에 살고 있다. 하루를 마칠 때에는 마그마에 잠겨 피로를 푼다.', 'Its magma-like blood circulates throughout its body. Its body’s heat can top 1,100 degrees F.'),
  ('sinnoh', 201, 126, true, '온몸이 늘 불타고 있다. 화재를 일으키는 원인 중 하나로 두려움의 대상이 되고 있다.', 'When it breathes deeply, heat waves form around its body, making it hard to see clearly.'),
  ('sinnoh', 202, 467, true, '화산의 화구에서 사는 동안 마그마 덩어리 모양의 기관을 가진 화산 같은 몸이 되었다.', 'When launching 3,600 degrees F fireballs, its body takes on a whitish hue from the intense heat.'),
  ('sinnoh', 203, 220, true, '좋은 냄새를 맡으면 뒷일을 생각하지 않고 냄새 나는 방향으로 대시해버린다.', 'It has a very sensitive nose. It can locate mushrooms, berries, and even hot springs buried under ice.'),
  ('sinnoh', 204, 221, true, '4개의 다리는 짧지만 발굽이 넓고 거칠거칠하므로 눈 위도 미끄러지지 않고 걸을 수 있다.', 'Covered by a shaggy coat, it is strong against the cold. Its tusks of ice thicken when it snows.'),
  ('sinnoh', 205, 473, true, '생긴 것처럼 힘이 장사다. 얼음으로 된 엄니는 추울수록 굵고 길어지면서 늠름해진다.', 'A frozen one was dug up from soil dating back 10,000 years. It woke up to much amazement.'),
  ('sinnoh', 206, 361, true, '추운 땅에서만 살 수 있다. 영하 100도의 환경에서도 건강하게 뛰어다닌다.', 'It is said that several SNORUNT gather under giant leaves and live together in harmony.'),
  ('sinnoh', 207, 362, true, '공기 중의 수분을 단숨에 얼게 하는 힘으로 먹이를 냉동시켜 버린다.', 'It prevents prey from escaping by instantaneously freezing moisture in the air.'),
  ('sinnoh', 208, 478, true, '마이너스 50도의 냉기를 뿜어 먹이를 얼린 뒤 거처로 가져가서 가지런히 나열한다.', 'It freezes prey by blowing its -58 degrees F breath. It is said to then secretly display its prey.'),
  ('sinnoh', 209, 359, true, '위험을 감지하는 능력이 있어 사람들로부터 재앙을 불러오는 포켓몬이라는 오해를 샀다.', 'Rumored to sense disasters with its horn, it became a target. It fled deep into the mountains.'),
  ('sinnoh', 210, 487, true, '난폭하다는 이유로 쫓겨났지만 깨어진 세계라고 전해지는 장소에서 조용히 원래 세계를 보고 있었다.', 'It was banished for its violence. It silently gazed upon the old world from the Distortion World.'),
  ('sinnoh', 210, 10063, false, '난폭하다는 이유로 쫓겨났지만 깨어진 세계라고 전해지는 장소에서 조용히 원래 세계를 보고 있었다.', 'It was banished for its violence. It silently gazed upon the old world from the Distortion World.'),
  ('sinnoh', 211, 485, true, '마그마처럼 타오르는 혈액이 몸에서 흐르고 있다. 화산의 동굴에 서식한다.', 'Its body is made of rugged steel. However, it is partially melted in spots because of its own heat.'),
  ('sinnoh', 212, 486, true, '다양한 재료로 포켓몬을 만든 후 대륙을 지금의 장소로 이동시켰다고 전해진다.', 'It is said to have made Pokémon that look like itself from a special ice mountain, rocks, and magma.'),
  ('sinnoh', 213, 488, true, '크레세리아의 날개를 가지고 자면 즐거운 꿈을 꿀 수 있다고 한다. 초승달의 화신으로 불리고 있다.', 'On nights around the quarter moon, the aurora from its tail extends and undulates beautifully.'),
  ('sinnoh', 214, 489, true, '따뜻한 바다를 떠돌고 있다. 아무리 먼 곳으로 흘러가도 태어난 장소로 반드시 돌아온다.', 'It drifts in warm seas. It always returns to where it was born, no matter how far it may have drifted.'),
  ('sinnoh', 215, 491, true, '사람들을 깊은 잠으로 끌어들여 꿈을 꾸게 하는 능력을 가지고 있다. 그믐달이 뜨는 밤에 활동한다.', 'To protect itself, it afflicts those around it with nightmares. However, it means no harm.'),
  ('sinnoh', 216, 492, true, '그라시데아꽃이 피는 계절에 감사의 마음을 전하기 위해 날아오른다고 전해진다.', 'The flowers all over its body burst into bloom if it is lovingly hugged and senses gratitude.'),
  ('sinnoh', 216, 10064, false, '그라시데아꽃이 피는 계절에 감사의 마음을 전하기 위해 날아오른다고 전해진다.', 'The flowers all over its body burst into bloom if it is lovingly hugged and senses gratitude.'),
  ('sinnoh', 217, 493, true, '우주가 아직 생기지 않았을 무렵에 처음으로 태어난 포켓몬이라고 신화 속에서 묘사된다.', 'It is said to have emerged from an egg in a place where there was nothing, then shaped the world.'),
  ('sinnoh', 217, 10041, false, '우주가 아직 생기지 않았을 무렵에 처음으로 태어난 포켓몬이라고 신화 속에서 묘사된다.', 'It is said to have emerged from an egg in a place where there was nothing, then shaped the world.'),
  ('sinnoh', 217, 10042, false, '우주가 아직 생기지 않았을 무렵에 처음으로 태어난 포켓몬이라고 신화 속에서 묘사된다.', 'It is said to have emerged from an egg in a place where there was nothing, then shaped the world.'),
